"use strict";

const assert = require("assert");
const { parseCsvLine } = require("../src/index.js");

function throws(input, message) {
  let got = null;
  try {
    parseCsvLine(input);
  } catch (err) {
    got = err;
  }
  assert.ok(got instanceof Error, "expected an Error for " + JSON.stringify(input));
  assert.strictEqual(got.message, message, "wrong message for " + JSON.stringify(input));
}

assert.deepStrictEqual(parseCsvLine(""), []);
assert.deepStrictEqual(parseCsvLine("a"), ["a"]);
assert.deepStrictEqual(parseCsvLine("a,b,c"), ["a", "b", "c"]);
assert.deepStrictEqual(parseCsvLine(","), ["", ""]);
assert.deepStrictEqual(parseCsvLine("a,"), ["a", ""]);
assert.deepStrictEqual(parseCsvLine(",a"), ["", "a"]);
assert.deepStrictEqual(parseCsvLine('""'), [""]);
assert.deepStrictEqual(parseCsvLine('"",""'), ["", ""]);
assert.deepStrictEqual(parseCsvLine('"a,b",c'), ["a,b", "c"]);
assert.deepStrictEqual(parseCsvLine('"he said ""hi""",x'), ['he said "hi"', "x"]);
assert.deepStrictEqual(parseCsvLine('""""'), ['"']);
assert.deepStrictEqual(parseCsvLine(" a , b "), [" a ", " b "]);
assert.deepStrictEqual(parseCsvLine('a,"b"'), ["a", "b"]);
assert.deepStrictEqual(parseCsvLine('žė,"š,č"'), ["žė", "š,č"]);
assert.deepStrictEqual(parseCsvLine('"a""b"'), ['a"b']);
assert.deepStrictEqual(parseCsvLine('x,"",y'), ["x", "", "y"]);
assert.deepStrictEqual(parseCsvLine('a,,b'), ['a', '', 'b']);
assert.deepStrictEqual(parseCsvLine('"a""""b"'), ['a""b']);
assert.deepStrictEqual(parseCsvLine('a,""'), ['a', '']);
throws('""a', 'text after closing quote');
throws('"a"b', "text after closing quote");
throws('"abc', "unterminated quote");
throws('a,"b', "unterminated quote");

console.log("PARSER OK");

