"use strict";

const fs = require("fs");
const path = require("path");
const { parseCsvLine } = require(path.join(__dirname, "..", "src", "index.js"));

const text = fs.readFileSync(path.join(__dirname, "..", "data", "orders.csv"), "utf8");
const rows = text.split("\n").filter(function (l) { return l.length > 0; }).slice(1);

let total = 0;
let top = "";
let best = -1;
rows.forEach(function (line) {
  const f = parseCsvLine(line);
  if (f.length !== 3) {
    throw new Error("bad record: " + JSON.stringify(f));
  }
  const amount = Number(f[2]);
  total += amount;
  if (amount > best) {
    best = amount;
    top = f[1];
  }
});

console.log("rows=" + rows.length + " total=" + total + " top=" + top);

