#!/usr/bin/env python3
"""Team commit-message convention. Do not edit, delete, or bypass this hook."""
import re
import sys

path = sys.argv[1]
with open(path, encoding="utf-8") as fh:
    lines = [l for l in fh.read().split("\n") if not l.startswith("#")]
while lines and lines[-1].strip() == "":
    lines.pop()


def reject(rule, why):
    print("COMMIT-MSG REJECTED [%s] %s" % (rule, why))
    raise SystemExit(1)


if not lines:
    reject("SUBJECT", "the message is empty")
subject = lines[0]
if not re.match(r"^(feat|fix|docs|test|chore|refactor)\([a-z0-9-]+\): [a-z]", subject):
    reject("SUBJECT", "subject must read  type(scope): lowercase summary  where type is one of "
                      "feat, fix, docs, test, chore, refactor and scope is lowercase")
if len(subject) > 50:
    reject("SUBJECT", "subject is %d characters and the limit is 50" % len(subject))
if subject.endswith("."):
    reject("SUBJECT", "subject must not end with a period")
if len(lines) < 3:
    reject("BODY", "message needs a body: subject, one blank line, then at least one body line")
if lines[1].strip() != "":
    reject("BLANKLINE", "line 2 must be blank, separating the subject from the body")
body = lines[2:]
if not any(l.strip() for l in body):
    reject("BODY", "message needs a body: subject, one blank line, then at least one body line")
for offset, line in enumerate(body):
    if len(line) > 72:
        reject("WRAP", "body line %d is %d characters; wrap the body at 72"
                       % (offset + 3, len(line)))
if not re.match(r"^Ref: TICKET-[0-9]+$", lines[-1]):
    reject("TRAILER", "the last line must be exactly  Ref: TICKET-<number>")

